"""Describe measured binary, including nonzero mapping overhead; no recompilation."""
import json,re
from common import *
r=runroot();p=r/'compiled/micro';b=json.loads((p/'build.json').read_text());s=(p/'micro.sass.txt').read_text();source=(p/'micro_consume.cu').read_text()
assert sha(p/'micro.cubin')==b['binaries']['micro.cubin'];assert sha(p/'micro_consume.cu')==b['sources']['micro_consume.cu'];assert 'MUFU.RCP' not in s;assert s.count('Function : micro_consume')==1
popc=re.findall(r'/\*([0-9a-f]+)\*/\s+POPC\s+([^;]+);',s);assert len(popc)==1
loads=[line.strip() for line in s.splitlines() if re.search(r'\bLDG\.',line)]
write(p/'SASS_SOURCE_AUDIT.json',dict(audited_at=utc(),cubin_sha256=sha(p/'micro.cubin'),source_sha256=sha(p/'micro_consume.cu'),sass_sha256=sha(p/'micro.sass.txt'),source_arguments='data input pointer, sum/diagnostic output pointers, scalar rw/mask/bias/data_class/colored/repeats; no schedule/home/SM lookup input pointer',popc_sites=popc,global_load_sites=loads,global_load_scope='Static instruction sites, not transaction counters. Source maps these loads to the integer payload only. No new scheduling-table load chain.',mapping_cost='CTA-invariant slot expression is in the thread prologue, outside all payload loops. SASS uses uniform registers/instructions for part of the expression but POPC writes an ordinary R register. Do not claim exactly one hardware execution per CTA: threads/warps execute the prologue. Mapping arithmetic, predicate and branch costs are included in measured N/E/B/T/X/Y/M/P paths.',literal_LUT='LOP3.LUT/ULOP3.LUT are boolean truth-table opcodes with immediates here, not loads from a scheduling lookup table.',mapping_vs_inner_loop='One static POPC site before consumer loops. Inner loop still performs address shifts/masks for the interleaved4KiB geometry; this is a controlled synthetic consumer, not an optimized production copy benchmark.',resources=dict(registers_per_thread=20,shared_bytes=1036,spill_store_bytes=0,spill_load_bytes=0),scope='Source/SASS audit of this compiled cubin; does not establish physical memory domains or physical-address affinity.'))
print('micro code audit',len(popc),'static POPC site;',len(loads),'payload LDG sites')
